/** Only local formula assets and bounded raster PNGs generated by region paint.
 * SVG/HTML data URLs and arbitrary network URLs are deliberately rejected. */
export function isGeometryImageUrl(value:string):boolean{
 if(/^\/geometry-assets\/formula-[1-5]\.jpg$/.test(value))return true;
 const prefix='data:image/png;base64,';
 if(!value.startsWith(prefix)||value.length>8_000_000)return false;
 const data=value.slice(prefix.length);
 if(data.length<44||data.length%4!==0||!/^iVBORw0KGgo[A-Za-z0-9+/]*={0,2}$/.test(data))return false;
 try{
  const header=atob(data.slice(0,44));
  if(header.slice(12,16)!=='IHDR')return false;
  const size=(offset:number)=>((header.charCodeAt(offset)*0x1000000)+(header.charCodeAt(offset+1)<<16)+(header.charCodeAt(offset+2)<<8)+header.charCodeAt(offset+3));
  const width=size(16),height=size(20);
  return width>0&&height>0&&width<=8192&&height<=8192&&width*height<=1_500_000;
 }catch{return false;}
}
